/* @autogenerated */
import { NgTemplateOutlet } from '@angular/common';
import {
  Component,
  computed,
  contentChild,
  contentChildren,
  effect,
  forwardRef,
  inject,
  Injector,
  input,
  OnDestroy,
  signal,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { DisplayProvider } from '@shared/data/display-provider';
import { Logger } from '@shared/context/observability/logger.service';
import { SelectionModel } from 'app/shared/data/selection-model';
import { LocalRouteStateService } from 'app/shared/interaction/local-route-state/local-route-state.service';
import { inlineIconCount } from './action-breakpoints';
import { ACTION_CONTAINER_REF } from './action-container.tokens';
import { ActionHostComponent } from './action-host.component';
import { ActionRouteSync } from './action-route-sync';
import { ActionRowMenuComponent } from './action-row-menu.component';
import { ActionSelectionBarComponent } from './action-selection-bar.component';
import { ActionToolbarComponent } from './action-toolbar.component';
import { Action, ItemMapper } from './action.model';

export type { ItemMapper } from './action.model';

/**
 * Reúne las acciones (`#action`) de una pantalla y las expone como plantillas para la lista
 * (`theToolbarTemplate`, `theContextTemplate`, `theSelectionTemplate`). Con `mapper`, la acción
 * activa se refleja en la URL; los contenedores anidados forman migas de pan.
 */
@Component({
  selector: 'action-container',
  standalone: true,
  imports: [
    NgTemplateOutlet,
    ActionHostComponent,
    ActionRowMenuComponent,
    ActionSelectionBarComponent,
    ActionToolbarComponent,
  ],
  styleUrl: 'action-container.component.scss',
  providers: [
    // Estado en la URL con el ciclo de vida de este contenedor
    LocalRouteStateService,
    // Este contenedor se expone como referencia inyectable
    { provide: ACTION_CONTAINER_REF, useExisting: forwardRef(() => ActionContainerComponent) },
  ],
  templateUrl: 'action-container.component.html',
})
export class ActionContainerComponent implements OnDestroy {
  private readonly logger = inject(Logger);
  private readonly routeSync = new ActionRouteSync(inject(LocalRouteStateService), inject(Injector));
  readonly parent: ActionContainerComponent | undefined =
    inject(ACTION_CONTAINER_REF, { optional: true, skipSelf: true }) ?? undefined;

  /** Acciones que se muestran como botón en la barra y en la cabecera; el resto va al menú "más". */
  maxIcons = input(2);
  name = input<string>('container');
  mapper = input<ItemMapper<any>>();
  display = input<DisplayProvider<any>>();

  actions = contentChildren<Action>('action');
  masterTemplate = contentChild<TemplateRef<any>>('masterTemplate');

  theToolbarTemplate = viewChild<TemplateRef<any>>('toolbarTemplate');
  theActiveTemplate = viewChild<TemplateRef<any>>('activeTemplate');
  theContextTemplate = viewChild<TemplateRef<any>>('contextualTemplate');
  theSelectionTemplate = viewChild<TemplateRef<any>>('selectionTemplate');

  readonly selectionModel = new SelectionModel<any>();
  current = signal<Action | undefined>(undefined);
  activeRender?: TemplateRef<any>;
  contextualconSize = inlineIconCount();

  leaf: ActionContainerComponent = this;
  breadcrumb: ActionContainerComponent[] = [];

  contextualActions = computed(() =>
    this.actions().filter((act) => act.name != this.current()?.name && act.contextual),
  );
  multipleActions = computed(() => this.visibleActions((act) => act.contextual && act.multiple));
  toolbarActions = computed(() => this.visibleActions((act) => !act.contextual).slice(0, this.maxIcons()));
  breadcrumActions = computed(() =>
    this.selectionModel.selected().length == 1 ? this.visibleActions((act) => act.contextual && !act.multiple) : [],
  );
  dialogActions = computed(() => this.breadcrumActions().slice(0, this.maxIcons()));
  dialogMenu = computed(() => this.breadcrumActions().slice(this.maxIcons()));

  constructor() {
    effect(() => {
      this.actions().forEach((action) => {
        action.container.set(this);
        action.selection = this.selectionModel.selected;
      });
    });
    effect(() => {
      const mapper = this.mapper();
      if (mapper) {
        this.routeSync.connect(this.name(), mapper, (action, items) => this.runAction(action, items));
      }
    });
  }

  ngOnDestroy(): void {
    this.routeSync.disconnect();
  }

  hasSelection() {
    return !this.current() && this.selectionModel.selected().length > 0;
  }

  hasMultiple() {
    return !!this.actions().find((act) => act.multiple);
  }

  showMenu(item: any) {
    const mapper = this.mapper();
    mapper?.load(mapper.display(item));
  }

  inlineActions(row: any) {
    return this.rowActions(row).slice(0, this.contextualconSize());
  }

  inlineMenu(row: any) {
    return this.rowActions(row).slice(this.contextualconSize());
  }

  defaultAction(items: any[]) {
    const candidate = this.actions().find(
      (act) => act.default() && this.contextMatch(act, items) && act.visible(items)() && act.enabled(items)(),
    );
    if (candidate) {
      this.executeAction(candidate.name, items);
    } else {
      this.logger.warn('ActionContainer: no default action');
    }
  }

  executeAction(name?: string, items?: any[]) {
    if (!this.routeSync.bound) {
      this.runAction(name, items);
      return;
    }
    let value: string | undefined;
    if (name && items && items.length > 1) {
      this.runAction(name, items);
    } else if (name && items?.length == 1) {
      value = name + ':' + this.mapper()?.display(items[0]);
    } else if (name) {
      value = name;
    } else {
      this.reset();
    }
    this.routeSync.go(this.name(), value);
  }

  close() {
    this.breadcrumb.forEach((ch) => ch.executeAction());
    this.executeAction();
    this.check();
  }

  check() {
    this.goUp([], this);
  }

  goUp(breadcrumb: ActionContainerComponent[], leaf: ActionContainerComponent) {
    if (this.parent) {
      this.parent.goUp(this !== leaf ? [this, ...breadcrumb] : breadcrumb, leaf);
    }
    setTimeout(() => {
      this.breadcrumb = this == leaf ? [] : [this, ...breadcrumb];
      this.leaf = leaf;
    });
  }

  private visibleActions(match: (action: Action) => boolean) {
    const selected = this.selectionModel.selected();
    return this.actions().filter((act) => match(act) && act.visible(selected)());
  }

  private rowActions(row: any) {
    return this.contextualActions().filter((act) => act.visible([row])());
  }

  /** Sin elementos: acciones generales; uno: contextuales; varios: múltiples. */
  private contextMatch(act: Action, items: any[]) {
    return items.length === 1 ? act.contextual : items.length > 1 ? act.multiple : !act.contextual;
  }

  private runAction(name?: string, items?: any[]) {
    if (!name) {
      this.reset();
      return;
    }
    const act = this.actions().find((action) => action.name == name);
    if (!act) {
      this.logger.warn('ActionContainer: nothing to execute');
      return;
    }
    this.selectionModel.select(items || []);
    this.current.set(act);
    const render = act.render();
    if (render) {
      this.activeRender = render;
    }
    act.run();
    this.check();
  }

  private reset() {
    this.current.set(undefined);
    this.activeRender = undefined;
    this.selectionModel.clearSelection();
  }
}
